BEGIN;
DO $$ DECLARE source catalog.source_versions;repo uuid;run uuid;ctx uuid;manifest uuid;j uuid;work jsonb;next_work jsonb;rejected boolean:=false;BEGIN
 SELECT * INTO source FROM catalog.source_versions ORDER BY path LIMIT 1;SELECT repository_id INTO repo FROM catalog.snapshots WHERE id=source.snapshot_id;
 INSERT INTO catalog.import_runs(snapshot_id,request_key,scope,manifest_digest,scanner_version,state,expected_count,parser_version) VALUES(source.snapshot_id,'queue-test-'||gen_random_uuid(),'{}',repeat('a',64),'synthetic','running',1,'synthetic') RETURNING id INTO run;
 INSERT INTO catalog.import_entries(run_id,path,blob_oid,sha256,byte_count,metadata,state,exercise_id,source_version_id) VALUES(run,source.path,repeat('a',40),source.sha256,1,'{"title":"Synthetic","state":"missing"}','imported',source.exercise_id,source.id);
 UPDATE catalog.import_runs SET state='completed',inventory_sealed=true,coverage_complete=true WHERE id=run;
 INSERT INTO catalog.import_heads(repository_id,run_id) VALUES(repo,run);
 INSERT INTO catalog.capability_manifests(source_version_id,detector_version,digest,manifest) VALUES(source.id,'queue-test',repeat('b',64),'{"candidateCapabilities":["native-text"],"unsupported":[]}') RETURNING id INTO manifest;
 INSERT INTO catalog.verifier_contexts(snapshot_id,digest,payload) VALUES(source.snapshot_id,repeat('c',64),'{"synthetic":true}') RETURNING id INTO ctx;
 INSERT INTO catalog.verifier_heads VALUES('local-practice',ctx,1);
 SELECT id INTO j FROM catalog.enqueue_verification(ARRAY[source.id,source.id],ctx,'synthetic','Dedup test')id LIMIT 1;
 IF (SELECT count(*) FROM catalog.verification_jobs)<>1 THEN RAISE EXCEPTION 'Duplicate job';END IF;
 work:=catalog.claim_verification('worker-a',2,1);IF work IS NULL THEN RAISE EXCEPTION 'No claim';END IF;
 IF catalog.claim_verification('worker-b',2,1) IS NOT NULL THEN RAISE EXCEPTION 'Concurrency limit bypass';END IF;
 UPDATE catalog.verification_jobs SET lease_until=now()-interval '1 second' WHERE id=j;
 IF catalog.heartbeat_verification(j,(work->>'token')::uuid,2) THEN RAISE EXCEPTION 'Expired heartbeat accepted';END IF;
 next_work:=catalog.claim_verification('worker-b',2,1);
 IF catalog.finish_verification(j,(work->>'token')::uuid,'{"technicalState":"error","error":"SYNTHETIC","cases":[]}') THEN RAISE EXCEPTION 'Stale worker accepted';END IF;
 IF NOT catalog.finish_verification(j,(next_work->>'token')::uuid,'{"technicalState":"error","error":"SYNTHETIC","cases":[]}') THEN RAISE EXCEPTION 'Current worker rejected';END IF;
 UPDATE catalog.verification_jobs SET technical_state='passed',state='needs-review' WHERE id=j;
 PERFORM catalog.review_verification(j,'requirements','accepted','synthetic','Synthetic requirements reviewed',true);
 IF catalog.verification_reviews_complete(j,(next_work->>'attemptId')::uuid) THEN RAISE EXCEPTION 'One review approved every category';END IF;
 PERFORM catalog.review_verification(j,'mathematical','accepted','synthetic','Synthetic mathematical review',true);
 PERFORM catalog.review_verification(j,'interaction','accepted','synthetic','Synthetic interaction review',true);
 PERFORM catalog.review_verification(j,'deployment','accepted','synthetic','Synthetic deployment review',true);
 IF NOT catalog.verification_reviews_complete(j,(next_work->>'attemptId')::uuid) THEN RAISE EXCEPTION 'Four reviews not complete';END IF;
 PERFORM catalog.review_verification(j,'mathematical','rejected','synthetic','Synthetic review revocation',true);
 IF catalog.verification_reviews_complete(j,(next_work->>'attemptId')::uuid) THEN RAISE EXCEPTION 'Revocation did not take effect';END IF;
 IF (SELECT count(*) FROM catalog.verification_attempts WHERE job_id=j)<>2 THEN RAISE EXCEPTION 'Attempt lost';END IF;
 BEGIN UPDATE catalog.verification_attempts SET result='{}' WHERE job_id=j;EXCEPTION WHEN SQLSTATE '55000' THEN rejected:=true;END;
 IF NOT rejected THEN RAISE EXCEPTION 'Old attempt modified';END IF;
 PERFORM catalog.control_verification(j,'retry','synthetic','Retry infrastructure failure');work:=catalog.claim_verification('worker-c',2,1);
 PERFORM catalog.control_verification(j,'cancel','synthetic','Stop in-flight work');
 IF catalog.finish_verification(j,(work->>'token')::uuid,'{"technicalState":"error","error":"SYNTHETIC","cases":[]}') THEN RAISE EXCEPTION 'Cancelled worker accepted';END IF;
 rejected:=false;BEGIN PERFORM catalog.control_verification(j,'retry','synthetic','Attempt cap');EXCEPTION WHEN SQLSTATE '55000' THEN rejected:=true;END;
 IF NOT rejected THEN RAISE EXCEPTION 'Attempt cap bypass';END IF;
END $$;
SELECT 'true'::json;
ROLLBACK;
